def F(iso, name, t, ospar=(), url=None, sub=None, parts=None, zh='', en='', step=1):
    return dict(iso=iso, name=name, t=t, ospar=list(ospar), url=url, sub=sub, parts=parts, zh=zh, en=en, step=step)


def F2(*a, **k):
    """第 2 步加入的列"""
    return F(*a, step=2, **k)


def F3(*a, **k):
    """第 3 步加入的列（浮動式）"""
    return F(*a, step=3, **k)


def F4(*a, **k):
    """第 4 步加入的列（台灣、日本、韓國、美國）"""
    return F(*a, step=4, **k)


def F5(*a, **k):
    """第 5 步加入的列（中國、越南）"""
    return F(*a, step=5, **k)


